SELECT p.*, t.code AS tax_code, t.rate AS tax_rate, t.inclusive AS tax_inclusive
FROM products p LEFT JOIN tax_rates t ON t.id = p.tax_rate_id

  AND (p.name ILIKE #{q} OR p.sku ILIKE #{q} OR p.barcode ILIKE #{q})
  AND p.category_id = #{categoryId}
  AND p.active = #{active}

ORDER BY p.name LIMIT #{size} OFFSET #{offset}

SELECT count(*) FROM products p

  AND (p.name ILIKE #{q} OR p.sku ILIKE #{q} OR p.barcode ILIKE #{q})
  AND p.category_id = #{categoryId}
  AND p.active = #{active}
